pattern.example:

def get_submit_button(page: Page):
    # Try multiple strategies
    locators = [
        page.get_by_role("button", name="Submit"),
        page.get_by_text("Submit"),
        page.locator("[type='submit']")
    ]
    for locator in locators:
        if locator.count() > 0:
            return locator
    raise Exception("Submit button not found")
